private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int limit = bb.limit();
    int pos = i;
    while (pos < limit) {
        int b = bb.get(pos) & 0xFF;
        int n;
        int c;
        if ((b & 0x80) == 0) {
            n = 0;
            c = b;
        } else if ((b & 0xE0) == 0xC0) {
            n = 1;
            c = b & 0x1F;
        } else if ((b & 0xF0) == 0xE0) {
            n = 2;
            c = b & 0x0F;
        } else if ((b & 0xF8) == 0xF0) {
            n = 3;
            c = b & 0x07;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 byte sequence at position " + pos);
        }
        if (pos + n >= limit) {
            throw new IllegalArgumentException("Incomplete UTF-8 character sequence at position " + pos);
        }
        for (int j = 0; j < n; j++) {
            int continueByte = bb.get(pos + j + 1) & 0xFF;
            if ((continueByte & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid continuation byte at position " + (pos + j + 1));
            }
            c = (c << 6) | (continueByte & 0x3F);
        }
        sb.append((char) c);
        pos += n + 1;
    }
    return pos;
}
